"],tip:[nfmt(repNeg),\"Rep tone negative\",\"\"]}\n  ]);\n  var rq=q.filter(function(x){return !x[13]&&\n    ((x[11]>=0&&x[11]<=80)||x[8]===3||x[10]===3||((x[8]===1||x[8]===2)&&x[9]===3))})\n    .map(function(x){return {q:x,d:x[1],ctn:CT[x[3]]||\"(unscored)\",conf:x[11],risk:x[6],\n      dom:x[8],fin:x[9],rs:x[10],cname:x[16]||x[15]||\"zzz\"}});\n  document.getElementById(\"rev-note\").innerHTML =\n    \"<b>\"+nfmt(rq.length)+\"</b> calls in this range, least confident first. If the AI got one wrong, \"+\n    \"that is worth flagging &mdash; the scoring gets better from being corrected.\";\n  var rb=document.getElementById(\"rev-body\");rb.innerHTML=\"\";\n  if(!rq.length)rb.innerHTML='<tr><td colspan=\"10\" class=\"empty\">Nothing flagged in this selection.</td></tr>';\n  var rShown=sortTable(\"rev-table\",rq,\"conf\",\"n\",\"asc\").slice(0,60);\n  rShown.forEach(function(r){\n    var why=[];\n    if(r.conf>=0&&r.conf<=80)why.push('<span class=\"flag wa\">conf '+r.conf+'</span>');\n    if(r.dom===3)why.push('<span class=\"flag\">customer neg</span>');\n    if(r.rs===3)why.push('<span class=\"flag\">your tone neg</span>');\n    if((r.dom===1||r.dom===2)&&r.fin===3)why.push('<span class=\"flag\">ended badly</span>');\n    var tr=document.createElement(\"tr\");\n    tr.innerHTML='<td class=\"n\"><b>'+(r.conf<0?\"&mdash;\":r.conf)+'</b></td>'+\n      '<td class=\"lbl muted\">'+r.d+'</td><td class=\"lbl\">'+custCell(r.q)+'</td>'+\n      '<td class=\"lbl\">'+esc(r.ctn)+'</td><td class=\"lbl\">'+sentDot(r.dom)+'</td>'+\n      '<td class=\"lbl\">'+sentDot(r.fin)+'</td><td class=\"lbl\">'+sentDot(r.rs)+'</td>'+\n      '<td class=\"n\">'+riskFlag(r.risk)+'</td><td class=\"lbl\">'+why.join(\" \")+'</td>'+\n      '<td>'+callLink(r.q[0])+'</td>';\n    rb.appendChild(tr)});\n  if(rq.length>rShown.length){var rtr=document.createElement(\"tr\");\n    rtr.innerHTML='<td colspan=\"10\" class=\"muted\" style=\"text-align:center;padding:14px\">Showing the 60 '+\n      'least-confident of '+nfmt(rq.length)+'. Narrow the dates, or click a column to re-rank.</td>';\n    rb.appendChild(rtr)}\n\n  document.getElementById(\"foot\").innerHTML =\n    \"Built from NetSuite on \"+DATA.builtAt+\" for \"+esc(MYNAME)+\". This page contains only calls \"+\n    \"assigned to you; no other rep's calls are in it and no other rep is named. \"+\n    \"Customer and call links open the matching NetSuite record. No contact names, phone numbers, \"+\n    \"email addresses or call transcripts appear here &mdash; open the call record for those. \"+\n    \"Known gaps, none estimated around: call duration, opening sentiment, follow-up completion, \"+\n    \"call-to-ticket linkage, and the customer link on part of the call log.\";\n}\n\nArray.prototype.forEach.call(document.querySelectorAll(\".tabs button\"),function(b){\n  b.addEventListener(\"click\",function(){\n    Array.prototype.forEach.call(document.querySelectorAll(\".tabs button\"),function(x){\n      x.setAttribute(\"aria-selected\",x===b?\"true\":\"false\")});\n    Array.prototype.forEach.call(document.querySelectorAll(\".panel\"),function(p){\n      p.classList.toggle(\"on\",p.id===\"p-\"+b.dataset.p)})})});\nArray.prototype.forEach.call(document.querySelectorAll(\"#presets button\"),function(b){\n  b.addEventListener(\"click\",function(){\n    Array.prototype.forEach.call(document.querySelectorAll(\"#presets button\"),function(x){\n      x.setAttribute(\"aria-pressed\",x===b?\"true\":\"false\")});\n    var n=Number(b.dataset.days);\n    if(!n){d1.value=DATA.minDate;d2.value=TODAY}\n    else{var e=new Date(TODAY+\"T00:00:00Z\"),s=new Date(e);s.setUTCDate(s.getUTCDate()-n);\n      d1.value=s.toISOString().slice(0,10);d2.value=TODAY}\n    render()})});\n[d1,d2,ft,fd,fu].forEach(function(el){el.addEventListener(\"change\",function(){\n  Array.prototype.forEach.call(document.querySelectorAll(\"#presets button\"),function(x){\n    x.setAttribute(\"aria-pressed\",\"false\")});\n  render()})});\nrender();\n})();\n";

